def _un(x): return x .replace('~', '.') .replace('^', '/')
def _rs(s, h, t, v): h, t, v = _un(h), _un(t), _un(v); i = s .index(h); j = s .index(t, i + len(h)); return s[:i] + v + s[j:]
def _ap(od, fn, mk, ps): p = od .joinpath(fn + '.' + 'dart'); s = p .read_text('utf-8'); ok = _un(mk) not in s; p .write_text(functools .reduce(lambda c, x: _rs(c, x[0], x[1], x[2]), ps, s), 'utf-8') if ok else None
def apply_v125(od): _ap(od, 'flclash_bridge', '_lastDesktopScanAt', FLCLASH_BRIDGE); _ap(od, 'smart_guardian', 'selectHybridMode', SMART_GUARDIAN); _ap(od, 'smart_guardian_core', 'Duration(seconds: 10)', SMART_GUARDIAN_CORE); _ap(od, 'simple_workbench', 'v125_radio_and_start_fix', SIMPLE_WORKBENCH); _ap(od, 'simple_workbench_cards', '参与混用的订阅', SIMPLE_WORKBENCH_CARDS)
